```zig
const std = @import("std");
const builtin = @import("builtin");
const net = std.net;
const http = std.http;
const json = std.json;

pub const GatewayConfig = struct {
    listen_addr: []const u8 = "0.0.0.0",
    listen_port: u16 = 8080,
    cerebras_api_key: []const u8,
    dragonfly_url: []const u8,
    modal_api_url: []const u8,
    kdb_host: []const u8 = "localhost",
    kdb_port: u16 = 5001,
    max_connections: u32 = 10000,
    thread_pool_size: u32 = 128,
    request_timeout_ms: u64 = 120000,
    cache_ttl_simple: u64 = 3600,
    cache_ttl_complex: u64 = 21600,
};

pub const RequestContext = struct {
    allocator: std.mem.Allocator,
    query: []const u8,
    complexity_score: f32,
    model_tier: ModelTier,
    cache_key: [64]u8,
    start_time_ms: u64,
    request_id: u64,
};

pub const ModelTier = enum {
    Fast,
    Balanced,
    Smart,
};

pub const SearchResult = struct {
    model_used: []const u8,
    latency_ms: u64,
    tokens_used: u32,
    cache_hit: bool,
    results: []Document,
};

pub const Document = struct {
    doc_id: u64,
    url: []const u8,
    title: []const u8,
    snippet: []const u8,
    score: f32,
    relevance: f32,
};

pub const GatewayState = struct {
    config: GatewayConfig,
    allocator: std.mem.Allocator,
    cerebras_client: *CerebrasClient,
    dragonfly_client: *DragonflyClient,
    modal_client: *ModalClient,
    kdb_logger: *KdbLogger,
    request_counter: u64 = 0,
    active_connections: u64 = 0,
    thread_pool: *std.Thread.Pool,
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const cerebras_key = try std.process.getEnvVarOwned(allocator, "CEREBRAS_API_KEY");
    defer allocator.free(cerebras_key);

    const dragonfly_url = try std.process.getEnvVarOwned(allocator, "DRAGONFLY_URL");
    defer allocator.free(dragonfly_url);

    const modal_url = try std.process.getEnvVarOwned(allocator, "MODAL_API_URL");
    defer allocator.free(modal_url);

    const config = GatewayConfig{
        .cerebras_api_key = cerebras_key,
        .dragonfly_url = dragonfly_url,
        .modal_api_url = modal_url,
    };

    var cerebras_client = try CerebrasClient.init(allocator, config.cerebras_api_key);
    defer cerebras_client.deinit();

    var dragonfly_client = try DragonflyClient.init(allocator, config.dragonfly_url);
    defer dragonfly_client.deinit();

    var modal_client = try ModalClient.init(allocator, config.modal_api_url);
    defer modal_client.deinit();

    var kdb_logger = try KdbLogger.init(allocator, config.kdb_host, config.kdb_port);
    defer kdb_logger.deinit();

    var thread_pool = try std.Thread.Pool.init(.{
        .allocator = allocator,
        .n_threads = config.thread_pool_size,
    });
    defer thread_pool.deinit();

    var state = GatewayState{
        .config = config,
        .allocator = allocator,
        .cerebras_client = &cerebras_client,
        .dragonfly_client = &dragonfly_client,
        .modal_client = &modal_client,
        .kdb_logger = &kdb_logger,
        .thread_pool = &thread_pool,
    };

    const address = try net.Address.parseIp(config.listen_addr, config.listen_port);
    var server = try address.listen(.{
        .reuse_address = true,
        .backlog = 1024,
    });
    defer server.deinit();

    std.debug.print("Gateway listening on {}:{}\n", .{ config.listen_addr, config.listen_port });

    var connection_counter: u64 = 0;
    while (true) {
        const connection = try server.accept();
        connection_counter += 1;

        if (connection_counter % 1000 == 0) {
            std.debug.print("Connections accepted: {}\n", .{connection_counter});
        }

        _ = try thread_pool.spawn(handleConnection, .{ &state, connection });
    }
}

fn handleConnection(state: *GatewayState, connection: net.Server.Connection) !void {
    defer connection.stream.close();

    var buffer: [65536]u8 = undefined;
    var read_buf = std.io.fixedBufferStream(&buffer);

    const bytes_read = try connection.stream.readAll(read_buf.buffer);
    if (bytes_read == 0) return;

    var request_ctx = RequestContext{
        .allocator = state.allocator,
        .query = "",
        .complexity_score = 0.0,
        .model_tier = .Balanced,
        .cache_key = undefined,
        .start_time_ms = std.time.milliTimestamp(),
        .request_id = state.request_counter,
    };

    state.request_counter += 1;

    const request_str = read_buf.buffer[0..bytes_read];

    const query = try parseQueryFromRequest(state.allocator, request_str);
    defer state.allocator.free(query);
    request_ctx.query = query;

    request_ctx.complexity_score = analyzeQueryComplexity(query);
    request_ctx.model_tier = selectModelTier(request_ctx.complexity_score);

    const cache_key_str = try std.fmt.allocPrint(state.allocator, "cache:query:{s}", .{query});
    defer state.allocator.free(cache_key_str);
    @memcpy(&request_ctx.cache_key, cache_key_str[0..@min(cache_key_str.len, 64)]);

    var cache_hit = false;
    var cached_result: ?[]const u8 = null;

    if (state.dragonfly_client.get(&request_ctx.cache_key)) |result| {
        cached_result = result;
        cache_hit = true;
    }

    if (cache_hit and cached_result != null) {
        try sendCachedResponse(connection.stream, cached_result.?);
        try logMetric(state, &request_ctx, true);
        return;
    }

    const vector_results = try state.modal_client.vectorSearch(query, 100);
    defer state.allocator.free(vector_results);

    const context_docs = try buildContextFromResults(state.allocator, vector_results);
    defer {
        for (context_docs) |doc| {
            state.allocator.free(doc);
        }
        state.allocator.free(context_docs);
    }

    const prompt = try buildPrompt(state.allocator, query, context_docs, request_ctx.model_tier);
    defer state.allocator.free(prompt);

    const response = try state.cerebras_client.complete(
        prompt,
        request_ctx.model_tier,
    );
    defer state.allocator.free(response);

    try sendStreamingResponse(connection.stream, response);

    const ttl: u64 = if (request_ctx.complexity_score > 0.7)
        state.config.cache_ttl_complex
    else
        state.config.cache_ttl_simple;

    _ = state.dragonfly_client.setex(
        &request_ctx.cache_key,
        response,
        ttl,
    ) catch |err| {
        std.debug.print("Cache write error: {}\n", .{err});
    };

    try logMetric(state, &request_ctx, false);
}

fn parseQueryFromRequest(allocator: std.mem.Allocator, request_str: []const u8) ![]const u8 {
    if (std.mem.indexOf(u8, request_str, "?q=")) |idx| {
        var start = idx + 3;
        var end = start;
        while (end < request_str.len and request_str[end] != ' ' and request_str[end] != '&') {
            end += 1;
        }
        return try allocator.dupe(u8, request_str[start..end]);
    }
    return try allocator.dupe(u8, "");
}

fn analyzeQueryComplexity(query: []const u8) f32 {
    var score: f32 = 0.0;

    const complex_keywords = [_][]const u8{ "compare", "vs", "implement", "code", "analyze", "explain", "deeply" };
    for (complex_keywords) |keyword| {
        if (std.mem.indexOf(u8, query, keyword) != null) {
            score += 0.3;
        }
    }

    if (query.len > 200) score += 0.4;
    if (std.mem.indexOf(u8, query, "deep research") != null) score += 0.5;

    return @min(score, 1.0);
}

fn selectModelTier(complexity: f32) ModelTier {
    if (complexity > 0.7) return .Smart;
    if (complexity > 0.4) return .Balanced;
    return .Fast;
}

fn buildContextFromResults(allocator: std.mem.Allocator, results: []const u8) ![][]const u8 {
    var docs = std.ArrayList([]const u8).init(allocator);
    var lines = std.mem.splitSequence(u8, results, "\n");

    while (lines.next()) |line| {
        if (line.len > 0) {
            try docs.append(try allocator.dupe(u8, line));
        }
    }

    return try docs.toOwnedSlice();
}

fn buildPrompt(allocator: std.mem.Allocator, query: []const u8, context: [][]const u8, tier: ModelTier) ![]const u8 {
    var prompt = std.ArrayList(u8).init(allocator);
    defer prompt.deinit();

    try prompt.appendSlice("Context:\n");
    for (context) |doc| {
        try prompt.appendSlice(doc);
        try prompt.appendSlice("\n");
    }

    try prompt.appendSlice("\nQuery: ");
    try prompt.appendSlice(query);
    try prompt.appendSlice("\n\nRespond thoroughly");

    if (tier == .Smart) {
        try prompt.appendSlice(", with deep reasoning.");
    } else if (tier == .Balanced) {
        try prompt.appendSlice(", with balanced detail.");
    } else {
        try prompt.appendSlice(" briefly.");
    }

    return try allocator.dupe(u8, prompt.items);
}

fn sendStreamingResponse(stream: net.Stream, response: []const u8) !void {
    const header = "HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nTransfer-Encoding: chunked\r\n\r\n";
    try stream.writeAll(header);

    var lines = std.mem.splitSequence(u8, response, "\n");
    while (lines.next()) |line| {
        if (line.len > 0) {
            const chunk = try std.fmt.allocPrint(std.heap.page_allocator, "data: {s}\n\n", .{line});
            defer std.heap.page_allocator.free(chunk);
            try stream.writeAll(chunk);
        }
    }

    try stream.writeAll("data: [DONE]\n\n");
}

fn sendCachedResponse(stream: net.Stream, cached: []const u8) !void {
    const header = "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nX-Cache: HIT\r\n\r\n";
    try stream.writeAll(header);
    try stream.writeAll(cached);
}

fn logMetric(state: *GatewayState, ctx: *RequestContext, cache_hit: bool) !void {
    const latency = std.time.milliTimestamp() - ctx.start_time_ms;
    _ = state.kdb_logger.logQuery(
        ctx.request_id,
        @tagName(ctx.model_tier),
        latency,
        0,
        cache_hit,
    ) catch |err| {
        std.debug.print("KDB log error: {}\n", .{err});
    };
}

pub const CerebrasClient = struct {
    allocator: std.mem.Allocator,
    api_key: []const u8,

    pub fn init(allocator: std.mem.Allocator, api_key: []const u8) !CerebrasClient {
        return CerebrasClient{
            .allocator = allocator,
            .api_key = api_key,
        };
    }

    pub fn deinit(self: *CerebrasClient) void {
        _ = self;
    }

    pub fn complete(self: *CerebrasClient, prompt: []const u8, tier: ModelTier) ![]const u8 {
        const url = "";
        const model = switch (tier) {
            .Fast => "qwen-235b",
            .Balanced => "gpt-oss-120b",
            .Smart => "glm-4.7-thinking",
        };

        var client = std.http.Client{ .allocator = self.allocator };
        defer client.deinit();

        const body = try std.fmt.allocPrint(self.allocator, 
            \\{{"model":"{s}","messages":[{{"role":"user","content":"{s}"}}],"stream":true}}
        , .{ model, prompt });
        defer self.allocator.free(body);

        var request = try client.request(.POST, try std.Uri.parse(url), .{
            .headers = .{ .content_type = "application/json" },
        }, .{});
        defer request.deinit();

        try request.writeAll(body);

        var response_buffer = std.ArrayList(u8).init(self.allocator);
        defer response_buffer.deinit();

        var buf: [4096]u8 = undefined;
        while (true) {
            const bytes = try request.read(&buf);
            if (bytes == 0) break;
            try response_buffer.appendSlice(buf[0..bytes]);
        }

        return try self.allocator.dupe(u8, response_buffer.items);
    }
};

pub const DragonflyClient = struct {
    allocator: std.mem.Allocator,
    url: []const u8,
    socket: ?net.Stream = null,

    pub fn init(allocator: std.mem.Allocator, url: []const u8) !DragonflyClient {
        return DragonflyClient{
            .allocator = allocator,
            .url = url,
        };
    }

    pub fn deinit(self: *DragonflyClient) void {
        if (self.socket) |s| {
            s.close();
        }
    }

    pub fn get(self: *DragonflyClient, key: *[64]u8) ?[]const u8 {
        if (self.socket == null) {
            self.connect() catch |err| {
                std.debug.print("Dragonfly connection error: {}\n", .{err});
                return null;
            };
        }

        var cmd_buf: [256]u8 = undefined;
        const cmd_len = std.fmt.bufPrint(&cmd_buf, "*2\r\n$3\r\nGET\r\n${}\r\n{s}\r\n", .{
            key.len,
            key,
        }) catch return null;

        self.socket.?.writeAll(cmd_buf[0..cmd_len.len]) catch return null;

        var resp_buf: [16384]u8 = undefined;
        const resp_len = self.socket.?.read(&resp_buf) catch return null;

        if (resp_len > 0 and resp_buf[0] == '$') {
            const result = parseRedisString(&resp_buf, resp_len);
            if (result) |r| {
                return r;
            }
        }

        return null;
    }

    pub fn setex(self: *DragonflyClient, key: *[64]u8, value: []const u8, ttl: u64) !bool {
        if (self.socket == null) {
            try self.connect();
        }

        var cmd_buf: [8192]u8 = undefined;
        const cmd_len = try std.fmt.bufPrint(&cmd_buf, 
            "*4\r\n$5\r\nSETEX\r\n${}\r\n{s}\r\n${}\r\n{}\r\n${}\r\n{s}\r\n",
            .{ key.len, key, @as(u64, @intCast(std.fmt.count("{}", .{ttl}))) + 1, ttl, value.len, value });

        try self.socket.?.writeAll(cmd_buf[0..cmd_len.len]);

        var resp_buf: [256]u8 = undefined;
        const resp_len = try self.socket.?.read(&resp_buf);

        return resp_len > 0 and resp_buf[0] == '+';
    }

    fn connect(self: *DragonflyClient) !void {
        var url_iter = std.mem.splitSequence(u8, self.url, ":");
        const host = url_iter.next() orelse "localhost";
        const port_str = url_iter.next() orelse "6379";
        const port = try std.fmt.parseInt(u16, port_str, 10);

        const address = try net.Address.parseIp(host, port);
        self.socket = try address.connect();
    }

    fn parseRedisString(buf: []const u8, len: usize) ?[]const u8 {
        if (len < 2 or buf[0] != '$') return null;

        var i: usize = 1;
        var size_str: [16]u8 = undefined;
        var size_idx: usize = 0;

        while (i < len and buf[i] != '\r' and size_idx < 15) {
            size_str[size_idx] = buf[i];
            size_idx += 1;
            i += 1;
        }

        const size = std.fmt.parseInt(usize, size_str[0..size_idx], 10) catch return null;
        if (buf[i] != '\r' or buf[i + 1] != '\n') return null;

        const data_start = i + 2;
        if (data_start + size > len) return null;

        return buf[data_start .. data_start + size];
    }
};

pub const ModalClient = struct {
    allocator: std.mem.Allocator,
    api_url: []const u8,

    pub fn init(allocator: std.mem.Allocator, api_url: []const u8) !ModalClient {
        return ModalClient{
            .allocator = allocator,
            .api_url = api_url,
        };
    }

    pub fn deinit(self: *ModalClient) void {
        _ = self;
    }

    pub fn vectorSearch(self: *ModalClient, query: []const u8, k: u32) ![]const u8 {
        var client = std.http.Client{ .allocator = self.allocator };
        defer client.deinit();

        const body = try std.fmt.allocPrint(self.allocator,
            \\{{"query":"{s}","k":{},"nprobe":128}}
        , .{ query, k });
        defer self.allocator.free(body);

        const url = try std.Uri.parse(self.api_url);

        var request = try client.request(.POST, url, .{
            .headers = .{ .content_type = "application/json" },
        }, .{});
        defer request.deinit();

        try request.writeAll(body);

        var response = std.ArrayList(u8).init(self.allocator);
        defer response.deinit();

        var buf: [4096]u8 = undefined;
        while (true) {
            const bytes = try request.read(&buf);
            if (bytes == 0) break;
            try response.appendSlice(buf[0..bytes]);
        }

        return try self.allocator.dupe(u8, response.items);
    }
};

pub const KdbLogger = struct {
    allocator: std.mem.Allocator,
    host: []const u8,
    port: u16,
    socket: ?net.Stream = null,
    buffer: std.ArrayList(u8),

    pub fn init(allocator: std.mem.Allocator, host: []const u8, port: u16) !KdbLogger {
        return KdbLogger{
            .allocator = allocator,
            .host = host,
            .port = port,
            .buffer = std.ArrayList(u8).init(allocator),
        };
    }

    pub fn deinit(self: *KdbLogger) void {
        if (self.socket) |s| {
            s.close();
        }
        self.buffer.deinit();
    }

    pub fn logQuery(self: *KdbLogger, request_id: u64, model: []const u8, latency_ms: u64, tokens: u32, cache_hit: bool) !void {
        if (self.socket == null) {
            try self.connect();
        }

        var msg: [512]u8 = undefined;
        const msg_len = try std.fmt.bufPrint(&msg,
            "QUERY|{}|{}|{}|{}|{}\n",
            .{ request_id, model, latency_ms, tokens, if (cache_hit) "1" else "0" });

        try self.buffer.appendSlice(msg[0..msg_len.len]);

        if (self.buffer.items.len > 10000) {
            try self.flush();
        }
    }

    fn connect(self: *KdbLogger) !void {
        const address = try net.Address.parseIp(self.host, self.port);
        self.socket = try address.connect();
    }

    fn flush(self: *KdbLogger) !void {
        if (self.socket) |s| {
            try s.writeAll(self.buffer.items);
            self.buffer.clearRetainingCapacity();
        }
    }
};
