const std = @import("std");

pub const ComplexityAnalyzer = struct {
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator) ComplexityAnalyzer {
        return ComplexityAnalyzer{ .allocator = allocator };
    }

    pub fn analyze(self: ComplexityAnalyzer, query: []const u8) RouterDecision {
        _ = self;
        var score: f32 = 0.0;

        const complex_keywords = [_][]const u8{
            "compare",     "versus",    "vs",        "implement",
            "code",        "algorithm", "analyze",   "explain",
            "deeply",      "thoroughly", "detailed",  "comprehensive",
            "architecture", "design",   "research",  "study",
        };

        for (complex_keywords) |keyword| {
            if (std.mem.indexOf(u8, query, keyword) != null) {
                score += 0.2;
            }
        }

        if (query.len > 200) score += 0.3;
        if (query.len > 500) score += 0.2;

        if (std.mem.indexOf(u8, query, "deep research") != null) score += 0.5;
        if (std.mem.indexOf(u8, query, "full analysis") != null) score += 0.4;

        const keyword_count = countKeywords(query, &complex_keywords);
        if (keyword_count > 3) score += 0.2;

        score = @min(score, 1.0);

        return if (score > 0.7)
            .Smart
        else if (score > 0.4)
            .Balanced
        else
            .Fast;
    }

    pub fn queryHash(self: ComplexityAnalyzer, query: []const u8) [64]u8 {
        _ = self;
        var hash: [64]u8 = undefined;
        var hasher = std.crypto.hash.sha2.Sha256.init(.{});
        hasher.update(query);
        var digest: [32]u8 = undefined;
        hasher.final(&digest);

        _ = std.fmt.bufPrint(&hash, "{}", .{std.fmt.fmtSliceHexLower(&digest)}) catch unreachable;
        return hash;
    }
};

pub const RouterDecision = enum {
    Fast,
    Balanced,
    Smart,
};

fn countKeywords(query: []const u8, keywords: []const []const u8) usize {
    var count: usize = 0;
    for (keywords) |keyword| {
        if (std.mem.indexOf(u8, query, keyword) != null) {
            count += 1;
        }
    }
    return count;
}

pub const Router = struct {
    allocator: std.mem.Allocator,
    analyzer: ComplexityAnalyzer,

    pub fn init(allocator: std.mem.Allocator) Router {
        return Router{
            .allocator = allocator,
            .analyzer = ComplexityAnalyzer.init(allocator),
        };
    }

    pub fn routeQuery(self: *Router, query: []const u8, cache_client: anytype, modal_client: anytype) !RouteResult {
        const complexity = self.analyzer.analyze(query);
        const cache_key = self.analyzer.queryHash(query);

        var cached = false;
        var cached_response: ?[]const u8 = null;

        if (cache_client.get(&cache_key)) |result| {
            cached = true;
            cached_response = result;
        }

        if (cached and cached_response != null) {
            return RouteResult{
                .model_tier = complexity,
                .cached_response = cached_response.?,
                .cache_hit = true,
                .documents = &[_][]const u8{},
            };
        }

        const docs = try modal_client.vectorSearch(query, 100);

        return RouteResult{
            .model_tier = complexity,
            .cached_response = "",
            .cache_hit = false,
            .documents = docs,
        };
    }
};

pub const RouteResult = struct {
    model_tier: RouterDecision,
    cached_response: []const u8,
    cache_hit: bool,
    documents: []const u8,
};
