const std = @import("std");

pub const StreamParser = struct {
    allocator: std.mem.Allocator,
    buffer: std.ArrayList(u8),

    pub fn init(allocator: std.mem.Allocator) StreamParser {
        return StreamParser{
            .allocator = allocator,
            .buffer = std.ArrayList(u8).init(allocator),
        };
    }

    pub fn deinit(self: *StreamParser) void {
        self.buffer.deinit();
    }

    pub fn parseSSEChunk(self: *StreamParser, chunk: []const u8) !?[]const u8 {
        try self.buffer.appendSlice(chunk);

        if (std.mem.indexOf(u8, self.buffer.items, "\n\n")) |end_idx| {
            const line_end = std.mem.lastIndexOf(u8, self.buffer.items[0..end_idx], "\n") orelse end_idx;
            const line = self.buffer.items[0..line_end];

            if (std.mem.startsWith(u8, line, "data: ")) {
                const data = line[6..];

                var remaining = std.ArrayList(u8).init(self.allocator);
                defer remaining.deinit();

                try remaining.appendSlice(self.buffer.items[end_idx + 2 ..]);

                self.buffer.clearRetainingCapacity();
                try self.buffer.appendSlice(remaining.items);

                if (std.mem.eql(u8, data, "[DONE]")) {
                    return null;
                }

                return try self.allocator.dupe(u8, data);
            }
        }

        return null;
    }

    pub fn validateUtf8(data: []const u8) bool {
        var i: usize = 0;
        while (i < data.len) {
            const byte = data[i];

            if (byte < 0x80) {
                i += 1;
            } else if (byte & 0xE0 == 0xC0) {
                if (i + 1 >= data.len) return false;
                i += 2;
            } else if (byte & 0xF0 == 0xE0) {
                if (i + 2 >= data.len) return false;
                i += 3;
            } else if (byte & 0xF8 == 0xF0) {
                if (i + 3 >= data.len) return false;
                i += 4;
            } else {
                return false;
            }
        }
        return true;
    }

    pub fn extractJsonTokenContent(json_str: []const u8) !?[]const u8 {
        if (std.mem.indexOf(u8, json_str, "\"content\":")) |idx| {
            var start = idx + 10;

            while (start < json_str.len and json_str[start] == ' ') {
                start += 1;
            }

            if (json_str[start] != '"') return null;
            start += 1;

            var end = start;
            while (end < json_str.len and json_str[end] != '"') {
                if (json_str[end] == '\\' and end + 1 < json_str.len) {
                    end += 2;
                } else {
                    end += 1;
                }
            }

            if (end >= json_str.len) return null;

            return json_str[start..end];
        }

        return null;
    }
};

pub const StreamResponseHandler = struct {
    allocator: std.mem.Allocator,
    parser: StreamParser,

    pub fn init(allocator: std.mem.Allocator) StreamResponseHandler {
        return StreamResponseHandler{
            .allocator = allocator,
            .parser = StreamParser.init(allocator),
        };
    }

    pub fn deinit(self: *StreamResponseHandler) void {
        self.parser.deinit();
    }

    pub fn handleStream(self: *StreamResponseHandler, stream_data: []const u8, callback: anytype) !void {
        var lines = std.mem.splitSequence(u8, stream_data, "\n");

        while (lines.next()) |line| {
            if (std.mem.startsWith(u8, line, "data: ")) {
                const data_part = line[6..];

                if (std.mem.eql(u8, data_part, "[DONE]")) {
                    break;
                }

                if (std.mem.eql(u8, data_part, "")) continue;

                if (self.parser.validateUtf8(data_part)) {
                    if (self.parser.extractJsonTokenContent(data_part)) |content| {
                        try callback(content);
                    }
                }
            }
        }
    }
};
