const std = @import("std");
const net = std.net;

pub const DragonflyRespProtocol = enum {
    SimpleString,
    Error,
    Integer,
    BulkString,
    Array,
    Null,
};

pub const DragonflyProtocolClient = struct {
    allocator: std.mem.Allocator,
    socket: net.Stream,
    password: ?[]const u8,

    pub fn init(allocator: std.mem.Allocator, socket: net.Stream, password: ?[]const u8) !DragonflyProtocolClient {
        var client = DragonflyProtocolClient{
            .allocator = allocator,
            .socket = socket,
            .password = password,
        };

        if (password != null) {
            try client.sendCommand(&[_][]const u8{ "AUTH", password.? });
            _ = try client.readResponse();
        }

        return client;
    }

    pub fn sendCommand(self: *DragonflyProtocolClient, args: []const []const u8) !void {
        var buffer = std.ArrayList(u8).init(self.allocator);
        defer buffer.deinit();

        const cmd = try std.fmt.allocPrint(self.allocator, "*{}\r\n", .{args.len});
        defer self.allocator.free(cmd);
        try buffer.appendSlice(cmd);

        for (args) |arg| {
            const arg_prefix = try std.fmt.allocPrint(self.allocator, "${}\r\n", .{arg.len});
            defer self.allocator.free(arg_prefix);
            try buffer.appendSlice(arg_prefix);
            try buffer.appendSlice(arg);
            try buffer.appendSlice("\r\n");
        }

        try self.socket.writeAll(buffer.items);
    }

    pub fn readResponse(self: *DragonflyProtocolClient) ![]const u8 {
        var buffer: [65536]u8 = undefined;
        const bytes_read = try self.socket.read(&buffer);

        if (bytes_read == 0) {
            return error.ConnectionClosed;
        }

        return try self.allocator.dupe(u8, buffer[0..bytes_read]);
    }

    pub fn get(self: *DragonflyProtocolClient, key: []const u8) !?[]const u8 {
        try self.sendCommand(&[_][]const u8{ "GET", key });
        const response = try self.readResponse();
        defer self.allocator.free(response);

        if (response[0] == '$') {
            if (std.mem.startsWith(u8, response, "$-1")) {
                return null;
            }

            var i: usize = 1;
            var len_str: [16]u8 = undefined;
            var len_idx: usize = 0;

            while (i < response.len and response[i] != '\r' and len_idx < 15) {
                len_str[len_idx] = response[i];
                len_idx += 1;
                i += 1;
            }

            const len = try std.fmt.parseInt(usize, len_str[0..len_idx], 10);
            i += 2;

            return try self.allocator.dupe(u8, response[i .. i + len]);
        }

        return null;
    }

    pub fn set(self: *DragonflyProtocolClient, key: []const u8, value: []const u8) !void {
        try self.sendCommand(&[_][]const u8{ "SET", key, value });
        _ = try self.readResponse();
    }

    pub fn setex(self: *DragonflyProtocolClient, key: []const u8, value: []const u8, ttl_seconds: u64) !void {
        const ttl_str = try std.fmt.allocPrint(self.allocator, "{}", .{ttl_seconds});
        defer self.allocator.free(ttl_str);

        try self.sendCommand(&[_][]const u8{ "SETEX", key, ttl_str, value });
        _ = try self.readResponse();
    }

    pub fn lpush(self: *DragonflyProtocolClient, key: []const u8, values: []const []const u8) !void {
        var args = std.ArrayList([]const u8).init(self.allocator);
        defer args.deinit();

        try args.append("LPUSH");
        try args.append(key);
        try args.appendSlice(values);

        try self.sendCommand(args.items);
        _ = try self.readResponse();
    }

    pub fn rpop(self: *DragonflyProtocolClient, key: []const u8) !?[]const u8 {
        try self.sendCommand(&[_][]const u8{ "RPOP", key });
        const response = try self.readResponse();
        defer self.allocator.free(response);

        if (response[0] == '$') {
            if (std.mem.startsWith(u8, response, "$-1")) {
                return null;
            }

            var i: usize = 1;
            var len_str: [16]u8 = undefined;
            var len_idx: usize = 0;

            while (i < response.len and response[i] != '\r' and len_idx < 15) {
                len_str[len_idx] = response[i];
                len_idx += 1;
                i += 1;
            }

            const len = try std.fmt.parseInt(usize, len_str[0..len_idx], 10);
            i += 2;

            return try self.allocator.dupe(u8, response[i .. i + len]);
        }

        return null;
    }

    pub fn sadd(self: *DragonflyProtocolClient, key: []const u8, members: []const []const u8) !i64 {
        var args = std.ArrayList([]const u8).init(self.allocator);
        defer args.deinit();

        try args.append("SADD");
        try args.append(key);
        try args.appendSlice(members);

        try self.sendCommand(args.items);
        const response = try self.readResponse();
        defer self.allocator.free(response);

        if (response[0] == ':') {
            return try std.fmt.parseInt(i64, response[1..], 10);
        }

        return 0;
    }

    pub fn sismember(self: *DragonflyProtocolClient, key: []const u8, member: []const u8) !bool {
        try self.sendCommand(&[_][]const u8{ "SISMEMBER", key, member });
        const response = try self.readResponse();
        defer self.allocator.free(response);

        if (response[0] == ':') {
            const val = try std.fmt.parseInt(i64, response[1..], 10);
            return val == 1;
        }

        return false;
    }

    pub fn zadd(self: *DragonflyProtocolClient, key: []const u8, score: f64, member: []const u8) !void {
        const score_str = try std.fmt.allocPrint(self.allocator, "{d}", .{score});
        defer self.allocator.free(score_str);

        try self.sendCommand(&[_][]const u8{ "ZADD", key, score_str, member });
        _ = try self.readResponse();
    }

    pub fn zrangebyscore(self: *DragonflyProtocolClient, key: []const u8, min: f64, max: f64, limit: usize) ![][]const u8 {
        var result = std.ArrayList([]const u8).init(self.allocator);

        const min_str = try std.fmt.allocPrint(self.allocator, "{d}", .{min});
        defer self.allocator.free(min_str);
        const max_str = try std.fmt.allocPrint(self.allocator, "{d}", .{max});
        defer self.allocator.free(max_str);
        const limit_str = try std.fmt.allocPrint(self.allocator, "{}", .{limit});
        defer self.allocator.free(limit_str);

        try self.sendCommand(&[_][]const u8{ "ZRANGEBYSCORE", key, min_str, max_str, "LIMIT", "0", limit_str });
        const response = try self.readResponse();
        defer self.allocator.free(response);

        if (response[0] == '*') {
            var i: usize = 1;
            var count_str: [16]u8 = undefined;
            var count_idx: usize = 0;

            while (i < response.len and response[i] != '\r' and count_idx < 15) {
                count_str[count_idx] = response[i];
                count_idx += 1;
                i += 1;
            }

            const count = try std.fmt.parseInt(usize, count_str[0..count_idx], 10);

            for (0..count) |_| {
                if (std.mem.indexOf(u8, response[i..], "$")) |dollar_idx| {
                    i += dollar_idx + 1;
                    var len_str: [16]u8 = undefined;
                    var len_idx: usize = 0;

                    while (i < response.len and response[i] != '\r' and len_idx < 15) {
                        len_str[len_idx] = response[i];
                        len_idx += 1;
                        i += 1;
                    }

                    if (len_idx > 0) {
                        const len = try std.fmt.parseInt(usize, len_str[0..len_idx], 10);
                        i += 2;

                        try result.append(try self.allocator.dupe(u8, response[i .. i + len]));
                        i += len + 2;
                    }
                }
            }
        }

        return try result.toOwnedSlice();
    }

    pub fn ping(self: *DragonflyProtocolClient) !bool {
        try self.sendCommand(&[_][]const u8{"PING"});
        const response = try self.readResponse();
        defer self.allocator.free(response);

        return std.mem.startsWith(u8, response, "+PONG");
    }

    pub fn flushdb(self: *DragonflyProtocolClient) !void {
        try self.sendCommand(&[_][]const u8{"FLUSHDB"});
        _ = try self.readResponse();
    }

    pub fn dbsize(self: *DragonflyProtocolClient) !i64 {
        try self.sendCommand(&[_][]const u8{"DBSIZE"});
        const response = try self.readResponse();
        defer self.allocator.free(response);

        if (response[0] == ':') {
            return try std.fmt.parseInt(i64, response[1..], 10);
        }

        return 0;
    }
};

pub const DragonflyConnectionPool = struct {
    allocator: std.mem.Allocator,
    host: []const u8,
    port: u16,
    password: ?[]const u8,
    pool: std.ArrayList(net.Stream),
    pool_size: usize,

    pub fn init(allocator: std.mem.Allocator, host: []const u8, port: u16, password: ?[]const u8, pool_size: usize) !DragonflyConnectionPool {
        var pool = std.ArrayList(net.Stream).init(allocator);

        for (0..pool_size) |_| {
            const address = try net.Address.parseIp(host, port);
            const socket = try address.connect();
            try pool.append(socket);
        }

        return DragonflyConnectionPool{
            .allocator = allocator,
            .host = host,
            .port = port,
            .password = password,
            .pool = pool,
            .pool_size = pool_size,
        };
    }

    pub fn deinit(self: *DragonflyConnectionPool) void {
        for (self.pool.items) |socket| {
            socket.close();
        }
        self.pool.deinit();
    }

    pub fn acquire(self: *DragonflyConnectionPool) !net.Stream {
        if (self.pool.items.len > 0) {
            return self.pool.pop();
        }

        const address = try net.Address.parseIp(self.host, self.port);
        return try address.connect();
    }

    pub fn release(self: *DragonflyConnectionPool, socket: net.Stream) !void {
        if (self.pool.items.len < self.pool_size) {
            try self.pool.append(socket);
        } else {
            socket.close();
        }
    }
};
