            .scores = std.ArrayList(f32).init(self.allocator),
            .documents = std.ArrayList(SearchDocument).init(self.allocator),
        };

        if (std.mem.indexOf(u8, response, "\"doc_ids\"")) |idx| {
            var i = idx + 10;
            while (i < response.len and response[i] != '[') {
                i += 1;
            }
            i += 1;

            while (i < response.len and response[i] != ']') {
                if (std.ascii.isDigit(response[i])) {
                    var num_str: [32]u8 = undefined;
                    var num_idx: usize = 0;
                    while (i < response.len and std.ascii.isDigit(response[i])) {
                        num_str[num_idx] = response[i];
                        num_idx += 1;
                        i += 1;
                    }
                    const doc_id = try std.fmt.parseInt(u64, num_str[0..num_idx], 10);
                    try result.doc_ids.append(doc_id);
                }
                i += 1;
            }
        }

        if (std.mem.indexOf(u8, response, "\"scores\"")) |idx| {
            var i = idx + 9;
            while (i < response.len and response[i] != '[') {
                i += 1;
            }
            i += 1;

            while (i < response.len and response[i] != ']') {
                if (response[i] == '-' or std.ascii.isDigit(response[i])) {
                    var num_str: [32]u8 = undefined;
                    var num_idx: usize = 0;
                    while (i < response.len and (response[i] == '-' or response[i] == '.' or std.ascii.isDigit(response[i]))) {
