            };

            var i: usize = 0;
            while (i < response.len) {
                if (response[i] == '-' or std.ascii.isDigit(response[i]) or response[i] == '.') {
                    var num_str: [32]u8 = undefined;
                    var num_idx: usize = 0;
                    while (i < response.len and (response[i] == '-' or response[i] == '.' or response[i] == 'e' or response[i] == 'E' or std.ascii.isDigit(response[i]))) {
                        num_str[num_idx] = response[i];
