        };

        var i: usize = 0;
        while (i < response.len) {
            if (std.mem.startsWith(u8, response[i..], "\"node_id\"")) {
                var node_id: u64 = 0;
                var score: f32 = 0.0;

                i += 9;
                while (i < response.len and response[i] != ':') {
                    i += 1;
                }
                i += 1;

                var num_str: [32]u8 = undefined;
                var num_idx: usize = 0;
                while (i < response.len and std.ascii.isDigit(response[i])) {
