                if (std.mem.indexOf(u8, response[i..], "\"score\"")) |score_idx| {
                    i += score_idx + 8;
                    while (i < response.len and response[i] != ':') {
                        i += 1;
                    }
                    i += 1;

                    num_idx = 0;
                    while (i < response.len and (response[i] == '-' or response[i] == '.' or std.ascii.isDigit(response[i]))) {
                        num_str[num_idx] = response[i];
                        num_idx += 1;
                        i += 1;
                    }
                    if (num_idx > 0) {
                        score = try std.fmt.parseFloat(f32, num_str[0..num_idx]);
                    }
                }

                try result.scores.append(PageRankScore{
                    .node_id = node_id,
                    .score = score,
                });
            }
            i += 1;
        }

        return result;
    }
};

pub const VectorSearchResult = struct {
    doc_ids: std.ArrayList(u64),
    scores: std.ArrayList(f32),
    documents: std.ArrayList(SearchDocument),

    pub fn deinit(self: *VectorSearchResult) void {
        self.doc_ids.deinit();
        self.scores.deinit();
        self.documents.deinit();
    }
};

pub const SearchDocument = struct {
    url: []const u8,
    title: []const u8,
    snippet: []const u8,
};

pub const EmbeddingResult = struct {
    embeddings: std.ArrayList(Embedding),

    pub fn deinit(self: *EmbeddingResult) void {
        for (self.embeddings.items) |*emb| {
            emb.values.deinit();
        }
        self.embeddings.deinit();
    }
};

pub const Embedding = struct {
    values: std.ArrayList(f32),
};

pub const PageRankResult = struct {
    scores: std.ArrayList(PageRankScore),

    pub fn deinit(self: *PageRankResult) void {
        self.scores.deinit();
    }
};

