const std = @import("std");
const net = std.net;

pub const KdbIpcMessage = struct {
    msg_type: u8,
    data: []const u8,
};

pub const KdbLogger = struct {
    allocator: std.mem.Allocator,
    host: []const u8,
    port: u16,
    socket: ?net.Stream,
    buffer: std.ArrayList(u8),
    flush_interval_ms: u64,
    last_flush: u64,

    pub fn init(allocator: std.mem.Allocator, host: []const u8, port: u16) !KdbLogger {
        return KdbLogger{
            .allocator = allocator,
            .host = host,
            .port = port,
            .socket = null,
            .buffer = std.ArrayList(u8).init(allocator),
            .flush_interval_ms = 100,
            .last_flush = std.time.milliTimestamp(),
        };
    }

    pub fn deinit(self: *KdbLogger) void {
        _ = self.flush() catch {};

        if (self.socket) |s| {
            s.close();
        }

        self.buffer.deinit();
    }

    pub fn connect(self: *KdbLogger) !void {
        const address = try net.Address.parseIp(self.host, self.port);
        self.socket = try address.connect();
    }

    pub fn logQuery(self: *KdbLogger, timestamp: i64, model: []const u8, latency_ms: u64, tokens: u32, cache_hit: bool) !void {
        var entry = std.ArrayList(u8).init(self.allocator);
        defer entry.deinit();

        const msg = try std.fmt.allocPrint(self.allocator,
            "time|{}|model|{}|latency|{}|tokens|{}|cache|{}\n",
            .{ timestamp, model, latency_ms, tokens, if (cache_hit) "1" else "0" });
        defer self.allocator.free(msg);

        try self.buffer.appendSlice(msg);

        const now = std.time.milliTimestamp();
        if (now - self.last_flush > self.flush_interval_ms or self.buffer.items.len > 10000) {
            try self.flush();
            self.last_flush = now;
        }
    }

    pub fn logCrawler(self: *KdbLogger, timestamp: i64, domain: []const u8, response_time_ms: u64, status_code: u16) !void {
        const msg = try std.fmt.allocPrint(self.allocator,
            "time|{}|domain|{}|response_time|{}|status|{}\n",
            .{ timestamp, domain, response_time_ms, status_code });
        defer self.allocator.free(msg);

        try self.buffer.appendSlice(msg);

        if (self.buffer.items.len > 10000) {
            try self.flush();
        }
    }

    pub fn logGpu(self: *KdbLogger, timestamp: i64, gpu_id: u8, temperature: f32, memory_used: u64, memory_total: u64, utilization: f32, power_draw: f32) !void {
        const msg = try std.fmt.allocPrint(self.allocator,
            "time|{}|gpu_id|{}|temperature|{}|memory_used|{}|memory_total|{}|utilization|{}|power|{}\n",
            .{ timestamp, gpu_id, temperature, memory_used, memory_total, utilization, power_draw });
        defer self.allocator.free(msg);

        try self.buffer.appendSlice(msg);

        if (self.buffer.items.len > 10000) {
            try self.flush();
        }
    }

    fn flush(self: *KdbLogger) !void {
        if (self.buffer.items.len == 0) return;

        if (self.socket == null) {
            try self.connect();
        }

        if (self.socket) |s| {
            s.writeAll(self.buffer.items) catch |err| {
                std.debug.print("KDB write error: {}\n", .{err});
                self.socket = null;
                return err;
            };
        }

        self.buffer.clearRetainingCapacity();
    }

    pub fn buildKdbRecord(allocator: std.mem.Allocator, comptime T: type, value: T) ![]const u8 {
        var buffer = std.ArrayList(u8).init(allocator);

        inline for (std.meta.fields(T)) |field| {
            const field_value = @field(value, field.name);
            const field_str = try std.fmt.allocPrint(allocator, "{s}|{any}\n", .{ field.name, field_value });
            defer allocator.free(field_str);
            try buffer.appendSlice(field_str);
        }

        return try buffer.toOwnedSlice();
    }

    pub fn nanotimestamp() i64 {
        return std.time.nanoTimestamp();
    }

    pub fn sendMessage(self: *KdbLogger, msg_type: u8, data: []const u8) !void {
        if (self.socket == null) {
            try self.connect();
        }

        var header: [4]u8 = undefined;
        header[0] = 1;
        header[1] = 0;
        var len = @as(u16, @intCast(data.len + 1));
        header[2] = @as(u8, @truncate(len >> 8));
        header[3] = @as(u8, @truncate(len));

        if (self.socket) |s| {
            try s.writeAll(&header);
            try s.writeAll(&[1]u8{msg_type});
            try s.writeAll(data);
        }
    }
};
