const std = @import("std");

pub const SSEStreamParser = struct {
    allocator: std.mem.Allocator,
    buffer: std.ArrayList(u8),

    pub fn init(allocator: std.mem.Allocator) SSEStreamParser {
        return SSEStreamParser{
            .allocator = allocator,
            .buffer = std.ArrayList(u8).init(allocator),
        };
    }

    pub fn deinit(self: *SSEStreamParser) void {
        self.buffer.deinit();
    }

    pub fn parseChunk(self: *SSEStreamParser, chunk: []const u8) !?ParsedMessage {
        try self.buffer.appendSlice(chunk);

        if (std.mem.indexOf(u8, self.buffer.items, "\n\n")) |end_idx| {
            const message_data = self.buffer.items[0..end_idx];

            var lines = std.mem.splitSequence(u8, message_data, "\n");

            var result_msg: ?[]const u8 = null;
            while (lines.next()) |line| {
                if (std.mem.startsWith(u8, line, "data: ")) {
                    result_msg = line[6..];
                }
            }

            var remaining = std.ArrayList(u8).init(self.allocator);
            defer remaining.deinit();

            if (end_idx + 2 < self.buffer.items.len) {
                try remaining.appendSlice(self.buffer.items[end_idx + 2 ..]);
            }

            self.buffer.clearRetainingCapacity();
            try self.buffer.appendSlice(remaining.items);

            if (result_msg) |msg| {
                if (std.mem.eql(u8, msg, "[DONE]")) {
                    return null;
                }

                if (!isValidUtf8(msg)) {
                    return error.InvalidUtf8;
                }

                return ParsedMessage{
                    .raw_json = try self.allocator.dupe(u8, msg),
                    .timestamp = std.time.timestamp(),
                };
            }
        }

        return null;
    }

    pub fn parseJsonContent(json_str: []const u8) !?[]const u8 {
        if (std.mem.indexOf(u8, json_str, "\"content\":")) |idx| {
            var start = idx + 10;

            while (start < json_str.len and json_str[start] == ' ') {
                start += 1;
            }

            if (start >= json_str.len or json_str[start] != '"') return null;
            start += 1;

            var end = start;
            var escaped = false;

            while (end < json_str.len) {
                if (escaped) {
                    escaped = false;
                } else if (json_str[end] == '\\') {
                    escaped = true;
                } else if (json_str[end] == '"') {
                    break;
                }
                end += 1;
            }

            if (end >= json_str.len) return null;

            return json_str[start..end];
        }

        return null;
    }

    pub fn extractTokenCount(json_str: []const u8) !u32 {
        if (std.mem.indexOf(u8, json_str, "\"usage\"")) |_| {
            if (std.mem.indexOf(u8, json_str, "\"total_tokens\"")) |idx| {
                var start = idx + 15;

                while (start < json_str.len and json_str[start] != ':') {
                    start += 1;
                }
                start += 1;

                var token_str: [16]u8 = undefined;
                var token_idx: usize = 0;

                while (start < json_str.len and token_idx < 15 and std.ascii.isDigit(json_str[start])) {
                    token_str[token_idx] = json_str[start];
                    token_idx += 1;
                    start += 1;
                }

                if (token_idx > 0) {
                    return try std.fmt.parseInt(u32, token_str[0..token_idx], 10);
                }
            }
        }

        return 0;
    }

    pub fn formatStreamingResponse(allocator: std.mem.Allocator, chunks: []const []const u8) ![]const u8 {
        var result = std.ArrayList(u8).init(allocator);
        defer result.deinit();

        for (chunks) |chunk| {
            try result.appendSlice(chunk);
        }

        return try allocator.dupe(u8, result.items);
    }
};

pub const ParsedMessage = struct {
    raw_json: []const u8,
    timestamp: i64,
};

fn isValidUtf8(data: []const u8) bool {
    var i: usize = 0;
    while (i < data.len) {
        const byte = data[i];

        if (byte < 0x80) {
            i += 1;
        } else if (byte & 0xE0 == 0xC0) {
            if (i + 1 >= data.len) return false;
            i += 2;
        } else if (byte & 0xF0 == 0xE0) {
            if (i + 2 >= data.len) return false;
            i += 3;
        } else if (byte & 0xF8 == 0xF0) {
            if (i + 3 >= data.len) return false;
            i += 4;
        } else {
            return false;
        }
    }
    return true;
}
