import std.stdio
import std.process
import std.fs
import std.sync
import std.time

class UrlFrontier {
  let @queue = []
  let @domains = []
  let @rate_limit = Map.new
  let @dragonfly_client = Dragonfly.new

  fn pub add_urls(urls: Array[String]) {
    urls.each fn(url) {
      let domain = parse_domain(url)
      if !@domains.contains?(domain) {
        @domains.push(domain)
        @rate_limit[domain] = Time.new
      }
      @queue.push(url)
    }
  }

  fn pub pop_url -> Option[String] {
    if @queue.size == 0 {
      return Option.None
    }

    let url = @queue.pop
    let domain = parse_domain(url)

    let last_crawl = @rate_limit[domain]
    let now = Time.now
    let elapsed = now - last_crawl

    if elapsed < 1000 {
      @queue.unshift(url)
      return Option.None
    }

    @rate_limit[domain] = now
    return Option.Some(url)
  }

  fn pub size -> Int {
    @queue.size
  }

  fn priv parse_domain(url: String) -> String {
    let parts = url.split("://")
    let host_part = parts[1]
    let path_split = host_part.split("/")
    path_split[0]
  }
}

class Fetcher {
  let @client = HttpClient.new
  let @user_agent = "NeuralSearchBot/1.0 (+"

  fn pub fetch(url: String) -> Result[String, String] {
    let result = @client.get(url, headers: [
      ("User-Agent", @user_agent),
      ("Accept-Encoding", "gzip, deflate")
    ], timeout: 30)

    match result {
      case Ok(response) -> {
        if response.status < 200 or response.status > 299 {
          return Result.Err("HTTP ${response.status}")
        }

        if response.headers.get("Content-Type").contains?("text/html") {
          return Result.Ok(response.body)
        } else {
          return Result.Err("Not HTML")
        }
      }
      case Err(error) -> Result.Err("Fetch failed: ${error}")
    }
  }
}

class HtmlParser {
  fn pub extract_links(html: String) -> Array[String] {
    let mut links = []
    let pattern = Regex.new("]+)")

    pattern.matches(html).each fn(match) {
      links.push(match[1])
    }

    links
  }

  fn pub extract_content(html: String) -> String {
    let mut content = html

    content = remove_boilerplate(content)
    content = decode_entities(content)
    content = normalize_whitespace(content)

    content
  }

  fn pub extract_metadata(html: String) -> Map[String, String] {
    let mut meta = Map.new

    let title_pattern = Regex.new("<title>([^<]+)</title>")
    let title_matches = title_pattern.matches(html)
    if title_matches.size > 0 {
      meta["title"] = title_matches[0][1]
    }

    let desc_pattern = Regex.new("<meta\\s+name=['\"]description['\"]\\s+content=['\"]([^'\"]+)")
    let desc_matches = desc_pattern.matches(html)
    if desc_matches.size > 0 {
      meta["description"] = desc_matches[0][1]
    }

    meta
  }

  fn priv remove_boilerplate(html: String) -> String {
    let mut result = html

    let tags_to_remove = ["nav", "header", "footer", "aside", "script", "style"]
    tags_to_remove.each fn(tag) {
      let pattern = Regex.new("<${tag}[^>]*>.*?</${tag}>", flags: "i|s")
      result = pattern.replace_all(result, "")
    }

    result
  }

  fn priv decode_entities(html: String) -> String {
    html
      .replace("&nbsp;", " ")
      .replace("&amp;", "&")
      .replace("&lt;", "<")
      .replace("&gt;", ">")
      .replace("&quot;", "\"")
  }

  fn priv normalize_whitespace(text: String) -> String {
    let pattern = Regex.new("\\s+")
    pattern.replace_all(text, " ").strip
  }
}

class Deduplicator {
  let @bloom_filter = BloomFilter.new(capacity: 100_000_000_000)
  let @visited_exact = Set.new

  fn pub mark_crawled(url: String, content_hash: String) {
    @bloom_filter.add(url)
    let sample = Random.int(0, 100)
    if sample == 0 {
      @visited_exact.insert(url)
    }
  }

  fn pub is_duplicate(url: String) -> Bool {
    @bloom_filter.contains?(url)
  }
}

class Scheduler {
  let @recrawl_queue = []

  fn pub schedule_recrawl(url: String, frequency: String) {
    let interval = match frequency {
      case "hourly" -> 3600
      case "daily" -> 86400
      case "weekly" -> 604800
      case "monthly" -> 2592000
      case _ -> 86400
    }

    let next_crawl = Time.now + Duration.new(seconds: interval)
    @recrawl_queue.push((next_crawl, url))
  }

  fn pub get_due_recrawls -> Array[String] {
    let now = Time.now
    let mut due = []

    @recrawl_queue.each fn(item) {
      let (crawl_time, url) = item
      if crawl_time <= now {
        due.push(url)
      }
    }

    due
  }
}

class CrawlerWorker {
  let @id = 0
  let @frontier = UrlFrontier.new
  let @fetcher = Fetcher.new
  let @parser = HtmlParser.new
  let @dedup = Deduplicator.new
  let @scheduler = Scheduler.new

  fn pub new(id: Int) -> CrawlerWorker {
    CrawlerWorker { @id = id }
  }

  fn pub run {
    loop {
      match @frontier.pop_url {
        case Option.Some(url) -> {
          stdio.print("Worker ${@id}: Fetching ${url}")

          match @fetcher.fetch(url) {
            case Ok(html) -> {
              if !@dedup.is_duplicate(url) {
                let content = @parser.extract_content(html)
                let metadata = @parser.extract_metadata(html)
                let links = @parser.extract_links(html)

                @dedup.mark_crawled(url, hash_content(content))

                store_document(url, content, metadata)

                @frontier.add_urls(links)

                @scheduler.schedule_recrawl(url, "daily")
              }
            }
            case Err(error) -> {
              stdio.print("Worker ${@id}: Error fetching ${url} - ${error}")
            }
          }
        }
        case Option.None -> {
          process.sleep(Duration.new(millis: 100))
        }
      }
    }
  }
}

fn store_document(url: String, content: String, metadata: Map[String, String]) {
  stdio.print("Storing document: ${url}")
}

fn hash_content(content: String) -> String {
  let hasher = Sha256.new
  hasher.update(content.as_bytes)
  hasher.finalize.to_hex
}

fn main {
  let num_workers = process.env("NUM_WORKERS").unwrap_or("100").parse(Int)
  let seed_urls = [
    "",
    "",
    "",
    "",
    ""
  ]

  let frontier = UrlFrontier.new
  frontier.add_urls(seed_urls)

  let mut workers = []
  (0...num_workers).each fn(i) {
    workers.push(CrawlerWorker.new(i))
  }

  workers.each fn(worker) {
    process.spawn(fn {
      worker.run
    })
  }

  loop {
    stdio.print("Queue size: ${frontier.size}")
    process.sleep(Duration.new(secs: 5))
  }
}
