```futhark
import "lib/github.com/diku-dk/futhark-ppl/dijkstra"

type embedding = [1024]f32
type doc_id = i64

def cosine_similarity [n] (a: [n]f32) (b: [n]f32) : f32 =
  let dot = f32.sum (map2 (*) a b)
  let norm_a = f32.sqrt (f32.sum (map (\ x -> x * x) a))
  let norm_b = f32.sqrt (f32.sum (map (\ x -> x * x) b))
  dot / (norm_a * norm_b + 1e-10)

def batch_cosine [m][n] (query: [n]f32) (docs: [m][n]f32) : [m]f32 =
  map (\ doc -> cosine_similarity query doc) docs

def top_k [m] (k: i64) (scores: [m]f32) (doc_ids: [m]doc_id) : ([k]doc_id, [k]f32) =
  let indices = iota m
  let sorted = sort_by (\ (_, s1) (_, s2) -> f32.compare s2 s1) (zip doc_ids scores)
  let top_docs = take k (map (.0) sorted)
  let top_scores = take k (map (.1) sorted)
  (top_docs, top_scores)

entry search [m][n] (query: [n]f32) (docs: [m][n]f32) (doc_ids: [m]doc_id) (k: i64) : ([k]doc_id, [k]f32) =
  let scores = batch_cosine query docs
  top_k k scores doc_ids

entry batch_search [q][m][n] (queries: [q][n]f32) (docs: [m][n]f32) (doc_ids: [m]doc_id) (k: i64) : [q]([k]doc_id, [k]f32) =
  map (\ query -> search query docs doc_ids k) queries

def ivf_search [c][n][m] (query: [n]f32) (centroids: [c][n]f32) (partitions: [c][]doc_id) (nprobe: i64) (embeddings: [m][n]f32) (doc_ids: [m]doc_id) (k: i64) : ([k]doc_id, [k]f32) =
  let centroid_scores = batch_cosine query centroids
  let top_centroids = iota c |> sort_by (\ i j -> f32.compare centroid_scores[j] centroid_scores[i]) |> take nprobe

  let mut candidates = []
  in (loop (i, candidates) = (0, candidates) while i < nprobe do
    let cluster_idx = top_centroids[i]
    let cluster_members = partitions[cluster_idx]
    (i + 1, candidates ++ cluster_members)
  ).1

  let candidate_embeddings = map (\ cand_id -> 
    let idx = unsafe_reduce (\ idx j -> if doc_ids[j] == cand_id then j else idx) 0 (iota m)
    embeddings[idx]
  ) candidates

  let scores = batch_cosine query candidate_embeddings
  top_k k scores candidates

def kmeans [m][n] (k: i64) (data: [m][n]f32) : [k][n]f32 =
  let centroids = take k data

  let centroids' = loop centroids do
    let assignments = map (\ point -> 
      let distances = map (\ c -> 
        let diff = map2 (-) point c
        f32.sqrt (f32.sum (map (\ x -> x * x) diff))
      ) centroids
      unsafe_reduce (\ idx i -> if distances[i] < distances[idx] then i else idx) 0 (iota k)
    ) data

    map (\ c_idx ->
      let members = filter (\ point_idx -> assignments[point_idx] == c_idx) (iota m)
      let member_points = map (\ idx -> data[idx]) members
      let member_count = length members |> i64.f32
      map (\ dim ->
        let sum = f32.sum (map (\ point -> point[dim]) member_points)
        sum / member_count
      ) (iota n)
    ) (iota k)

  centroids'

entry pq_encode [n] (embedding: [n]f32) : [64]u8 =
  let subvector_size = n / 64
  map (\ i ->
    let subvec = take subvector_size (drop (i * subvector_size) embedding)
    let max_val = unsafe_reduce f32.max subvec[0] subvec
    let min_val = unsafe_reduce f32.min subvec[0] subvec
    let range = max_val - min_val
    let normalized = map (\ x -> (x - min_val) / (range + 1e-10)) subvec
    let quantized = unsafe_reduce (\ idx j -> if normalized[j] > 0.5 then idx + 1 else idx) 0 (iota subvector_size)
    u8.i32 quantized
  ) (iota 64)

entry build_knn_graph [m][n] (embeddings: [m][n]f32) (k: i64) : [m][k]i64 =
  let pairwise = map (\ i ->
    map (\ j ->
      if i == j then 0.0
      else cosine_similarity embeddings[i] embeddings[j]
    ) (iota m)
  ) (iota m)

  map (\ i ->
    let scores = pairwise[i]
    let indices = iota m
    let sorted = sort_by (\ j1 j2 -> f32.compare scores[j2] scores[j1]) indices
    take k (drop 1 sorted)
  ) (iota m)
