typedef struct {
    uint32_t vocab_size;
    uint32_t** token_ids;
    char** tokens;
} Vocabulary;

terra create_vocabulary(uint32_t vocab_size)
    return Vocabulary {
        vocab_size = vocab_size,
        token_ids = [&uint32_t](std.malloc(vocab_size * sizeof(uint32_t))),
        tokens = [&int8](std.malloc(vocab_size * sizeof(int8)))
    }
end

terra free_vocabulary(vocab: Vocabulary)
    std.free(vocab.token_ids)
    std.free(vocab.tokens)
end

terra wordpiece_tokenize(text: &int8, text_len: uint64, vocab: Vocabulary, max_tokens: uint64)
    var result = [&uint32](std.malloc(max_tokens * sizeof(uint32_t)))
    var token_count: uint64 = 0
    var i: uint64 = 0

    while i < text_len and token_count < max_tokens do
        var j = i + 1
        while j < text_len and not isspace(text[j]) do
            j = j + 1
        end

        var word_len = j - i
        var found = false

        while word_len > 0 and not found do
            for k = 0, vocab.vocab_size do
                if vocab.token_ids[k] >= 0 then
                    var token_ptr = vocab.tokens[k]
                    var matches = true

                    for m = 0, word_len do
                        if text[i + m] ~= token_ptr[m] then
                            matches = false
                            break
                        end
                    end

                    if matches then
                        result[token_count] = vocab.token_ids[k]
                        token_count = token_count + 1
                        i = i + word_len
                        found = true
                        break
                    end
                end
            end

            if not found then
                word_len = word_len - 1
            end
        end

        if not found then
            result[token_count] = 100
            token_count = token_count + 1
            i = j
        end
    end

    return result, token_count
end

terra bpe_tokenize(text: &int8, text_len: uint64, merge_rules: &int8, num_merges: uint32) : &uint32, uint64
    var result = [&uint32](std.malloc(10000 * sizeof(uint32_t)))
    var token_count: uint64 = 0
    var i: uint64 = 0

    while i < text_len do
        var j = i
        while j < text_len and not isspace(text[j]) do
            j = j + 1
        end

        var word = [&int8](std.malloc((j - i + 1) * sizeof(int8)))
        std.memcpy(word, text + i, j - i)
        word[j - i] = 0

        for m = 0, num_merges do
            var pos: uint64 = 0
            while pos < std.strlen(word) - 1 do
                var pair_match = true
                var pair_len = 0
                while merge_rules[pair_len] ~= 0 do
                    if word[pos + pair_len] ~= merge_rules[pair_len] then
                        pair_match = false
                        break
                    end
                    pair_len = pair_len + 1
                end

                if pair_match then
                    std.memmove(word + pos, word + pos + pair_len, std.strlen(word + pos + pair_len) + 1)
                else
                    pos = pos + 1
                end
            end
        end

        i = j + 1
    end

    return result, token_count
end

terra encode_tokens(text: &int8, vocab_size: uint32) : &uint32, uint64
    var tokens = [&uint32](std.malloc(10000 * sizeof(uint32_t)))
    var count: uint64 = 0
    var i: uint64 = 0
    var text_len = std.strlen(text)

    while i < text_len and count < 10000 do
        var j = i
        while j < text_len and not isspace(text[j]) do
            j = j + 1
        end

        if j > i then
            tokens[count] = (text[i] - 97) % vocab_size
            count = count + 1
        end
        i = j + 1
    end

    return tokens, count
end

terra normalize_text(text: &int8) : &int8
    var result = [&int8](std.malloc(std.strlen(text) + 1))
    var out_idx: uint64 = 0
    var in_idx: uint64 = 0
    var last_was_space = true

    while text[in_idx] ~= 0 do
        var ch = text[in_idx]

        if isspace(ch) then
            if not last_was_space then
                result[out_idx] = 32
                out_idx = out_idx + 1
                last_was_space = true
            end
        else
            if isupper(ch) then
                result[out_idx] = tolower(ch)
            else
                result[out_idx] = ch
            end
            out_idx = out_idx + 1
            last_was_space = false
        end

        in_idx = in_idx + 1
    end

    result[out_idx] = 0
    return result
end
