import modal
import numpy as np
import json
from typing import List, Dict, Tuple

app = modal.App("neural-search-vector")

gpu_config = modal.gpu.A100(count=8)

vector_search_image = (
    modal.Image.debian_slim()
    .pip_install("numpy", "faiss-gpu", "torch", "pydantic")
)

@app.cls(
    gpu=gpu_config,
    image=vector_search_image,
    container_idle_timeout=600,
    allow_concurrent_requests=100
)
class VectorSearchEngine:
    def __enter__(self):
        import faiss
        import torch

        self.device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
        self.index_dimension = 1024
        self.index = faiss.IndexFlatIP(self.index_dimension)
        self.doc_id_mapping = {}
        self.doc_count = 0

    @modal.method()
    def add_vectors(self, doc_ids: List[int], embeddings: np.ndarray):
        embeddings_normalized = embeddings / (np.linalg.norm(embeddings, axis=1, keepdims=True) + 1e-10)
        self.index.add(embeddings_normalized.astype(np.float32))

        for i, doc_id in enumerate(doc_ids):
            self.doc_id_mapping[self.doc_count] = doc_id
            self.doc_count += 1

    @modal.method()
    def search(self, query_embedding: np.ndarray, k: int = 100, nprobe: int = 128) -> Dict:
        import torch

        query_normalized = query_embedding / (np.linalg.norm(query_embedding) + 1e-10)
        query_tensor = torch.from_numpy(query_normalized.astype(np.float32)).unsqueeze(0).to(self.device)

        distances, indices = self.index.search(query_tensor.cpu().numpy(), k)

        doc_ids = [self.doc_id_mapping.get(int(idx), -1) for idx in indices[0]]
        scores = distances[0].tolist()

        return {
            "doc_ids": doc_ids,
            "scores": scores,
            "k": k
        }

    @modal.method()
    def batch_search(self, query_embeddings: List[np.ndarray], k: int = 100) -> List[Dict]:
        results = []
        for query_emb in query_embeddings:
            result = self.search(query_emb, k)
            results.append(result)
        return results

    @modal.method()
    def get_stats(self) -> Dict:
        return {
            "index_size": self.index.ntotal,
            "dimension": self.index_dimension,
            "doc_count": self.doc_count
        }

@app.function(image=vector_search_image)
def vector_search_endpoint(query_embedding: List[float], k: int, nprobe: int):
    search_engine = VectorSearchEngine()
    embedding_array = np.array(query_embedding, dtype=np.float32)
    result = search_engine.search(embedding_array, k, nprobe)
    return result

@app.function(image=vector_search_image)
def batch_embed(texts: List[str], max_length: int = 512) -> List[List[float]]:
    import torch
    from transformers import AutoTokenizer, AutoModel

    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    tokenizer = AutoTokenizer.from_pretrained("microsoft/deberta-v3-base")
    model = AutoModel.from_pretrained("microsoft/deberta-v3-base").to(device)

    embeddings = []

    with torch.no_grad():
        for text in texts:
            inputs = tokenizer(text, max_length=max_length, truncation=True, return_tensors="pt").to(device)
            outputs = model(**inputs)

            last_hidden = outputs.last_hidden_state
            pooled = last_hidden.mean(dim=1).squeeze().cpu().numpy()

            embeddings.append(pooled.tolist())

    return embeddings

@app.function(image=vector_search_image)
def pagerank_compute(graph_json: str, num_iterations: int = 20, damping: float = 0.85) -> Dict:
    import json
    import networkx as nx

    graph_data = json.loads(graph_json)
    G = nx.DiGraph()

    for node_id, neighbors in graph_data.items():
        G.add_node(int(node_id))
        for neighbor in neighbors:
            G.add_edge(int(node_id), neighbor)

    pagerank_scores = nx.pagerank(G, alpha=damping, max_iter=num_iterations)

    return {
        "scores": {str(k): v for k, v in pagerank_scores.items()},
        "num_nodes": G.number_of_nodes(),
        "num_edges": G.number_of_edges()
    }

if __name__ == "__main__":
    app.run()
