Python embedding_encode.py

```python
import modal
import numpy as np
from typing import List, Dict
import torch
from transformers import AutoTokenizer, AutoModel

app = modal.App("neural-search-embedding")

embedding_image = (
    modal.Image.debian_slim()
    .pip_install("torch", "transformers", "numpy", "deepspeed")
)

@app.cls(
    gpu=modal.gpu.A100(count=4),
    image=embedding_image,
    container_idle_timeout=300,
    allow_concurrent_requests=50
)
class EmbeddingEncoder:
    def __enter__(self):
        self.device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
        self.tokenizer = AutoTokenizer.from_pretrained("microsoft/deberta-v3-large")
        self.model = AutoModel.from_pretrained("microsoft/deberta-v3-large").to(self.device)
        self.model.eval()

    @modal.method()
    def encode_batch(self, texts: List[str], max_length: int = 512) -> Dict:
        embeddings = []

        with torch.no_grad():
            for text in texts:
                inputs = self.tokenizer(
                    text,
                    max_length=max_length,
                    truncation=True,
                    return_tensors="pt"
                ).to(self.device)

                outputs = self.model(**inputs)

                last_hidden = outputs.last_hidden_state
                attention_mask = inputs["attention_mask"]

                masked_hidden = last_hidden * attention_mask.unsqueeze(-1)
                pooled = masked_hidden.sum(dim=1) / attention_mask.sum(dim=1, keepdim=True)

                normalized = torch.nn.functional.normalize(pooled, p=2, dim=1)

                embeddings.append(normalized.squeeze().cpu().numpy().tolist())

        return {
            "embeddings": embeddings,
            "count": len(embeddings),
            "dimension": 1024
        }

    @modal.method()
    def encode_streaming(self, text_stream: List[str], max_length: int = 512):
        for text in text_stream:
            result = self.encode_batch([text], max_length)
            yield result

@app.function(image=embedding_image)
def encode_documents(documents: List[Dict], max_length: int = 512) -> List[Dict]:
    encoder = EmbeddingEncoder()

    texts = [doc.get("content", "") for doc in documents]
    embedding_result = encoder.encode_batch(texts, max_length)

    result_docs = []
    for i, doc in enumerate(documents):
        doc_copy = doc.copy()
        doc_copy["embedding"] = embedding_result["embeddings"][i]
        result_docs.append(doc_copy)

    return result_docs

if __name__ == "__main__":
    app.run()
