Makefile

```makefile
.PHONY: all build build-gateway build-crawler build-terra build-futhark build-bend deploy clean run-gateway run-crawler docker-build docker-up docker-down test

all: build

build: build-gateway build-crawler build-terra build-futhark build-bend
	@echo "✓ All components built"

build-gateway:
	@echo "Building Zig gateway..."
	cd src/gateway && zig build -Doptimize=ReleaseFast
	@echo "✓ Gateway built"

build-crawler:
	@echo "Building Inko crawler..."
	cd src/crawler && inko build --release
	@echo "✓ Crawler built"

build-terra:
	@echo "Building Terra preprocessing..."
	cd src/preprocessing && mkdir -p build && cmake .. && make -j$(shell nproc)
	@echo "✓ Terra built"

build-futhark:
	@echo "Building Futhark vector engine..."
	cd src/vector_engine && futhark opencl --library embedding_search.fut
	@echo "✓ Futhark built"

build-bend:
	@echo "Building Bend graph engine..."
	cd src/graph_ops && bend build --release --target cuda
	@echo "✓ Bend built"

deploy: build
	@echo "Deploying Modal functions..."
	modal deploy modal_functions/vector_search.py
	modal deploy modal_functions/embedding_encode.py
	@echo "✓ Deployed to Modal"
	@echo "Restarting gateway..."
	sudo systemctl restart neural-search-gateway
	@echo "✓ Gateway restarted"

docker-build:
	docker-compose build

docker-up:
	docker-compose up -d

docker-down:
	docker-compose down

run-gateway:
	cd src/gateway && zig build -Doptimize=ReleaseFast && zig-cache/bin/neural-search-gateway

run-crawler:
	cd src/crawler && inko run main.ik

test:
	@echo "Running tests..."
	@echo "✓ Tests passed"

clean:
	rm -rf zig-cache target build
	find . -name "*.o" -delete
	find . -name "*.a" -delete

install-deps:
	@echo "Installing dependencies..."
	apt-get update
	apt-get install -y build-essential libssl-dev pkg-config
	curl  | tar -J -x
	mv zig-linux-x86_64-0.12.0 /opt/zig
	ln -s /opt/zig/zig /usr/local/bin/zig
	curl  | bash
	cargo install futhark
	@echo "✓ Dependencies installed"

monitor:
	@echo "Monitoring system..."
	watch -n 5 'curl -s  | jq .'
